<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ApiKeyClient\Domain\ValueObject\Holder\ApiKeyClientScopesAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ApiKeyClientScopesAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class ApiKeyClientScopesAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getScopes returns null on a freshly created holder.
     */
    public function testScopesNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithApiKeyClientScopesAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isScopesAssigned());
        $this->assertNull($holder->getScopes());
    }
}
class ImplWithApiKeyClientScopesAttributeHolderUnitTest
{
    use ApiKeyClientScopesAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedScopesRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultScopes();
    }
}
